detail.request-body:
{"query":"query ($id: ID!, $country: CountryCode!, $variantLimit: Int!) {
      product(id: $id) {
        id: legacyResourceId
        title
        handle
        status
        media: featuredMedia {
          preview {
            image {
              url
            }
          }
        }
        variantsCount {
          count
          precision
        }
        variants: variants(first: $variantLimit) {
          nodes {
            id: legacyResourceId
            title
            media(first: 5) {
              nodes {
                id
                mediaContentType
                status
                preview {
                  image {
                    url
                  }
                }
              }
            }
            contextualPricing(context: {country: $country}) {
              price {
                amount
                currencyCode
              }
            }
            price
            available: availableForSale
            inventoryQuantity
            inventoryItem {
              tracked
            }
            metafields: metafields(first: 20) {
              nodes {
                id
                key
                value
              }
            }
          }
          pageInfo {
            hasNextPage
            hasPreviousPage
            endCursor
          }
        }
      }
    }","variables":{"id":"gid://shopify/Product/9429080440987","country":"VN","variantLimit":20}}
